-- Филиалы магазина
CREATE TABLE IF NOT EXISTS slshop_branches (
  id SERIAL PRIMARY KEY,
  name VARCHAR(120) NOT NULL UNIQUE,
  address VARCHAR(255),
  phone VARCHAR(50),
  is_default BOOLEAN DEFAULT FALSE,
  is_active BOOLEAN DEFAULT TRUE,
  sort_order INTEGER DEFAULT 100,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

ON CONFLICT (name) DO NOTHING;

-- Привязка товара к филиалу/складу
ALTER TABLE slshop_items ADD COLUMN IF NOT EXISTS branch_id INTEGER REFERENCES slshop_branches(id);
CREATE INDEX IF NOT EXISTS idx_slshop_items_branch ON slshop_items(branch_id);

-- Назначим товары без филиала на Кирова 7 по умолчанию
UPDATE slshop_items SET branch_id = (SELECT id FROM slshop_branches WHERE name='Кирова 7') WHERE branch_id IS NULL;

-- Расширенный справочник описаний моделей
ON CONFLICT DO NOTHING;
